module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]   cnt50;
    logic   [31:0]   cnt72;
    always_ff @(posedge clk50) begin
        if (cnt50 == COUNT_LIMIT - 1) begin
            cnt50 <= 0;
        end
        else begin
            cnt50 <= cnt50 + 1;
        end
    end
    always_ff @(posedge clk72) begin
        if (cnt72 == COUNT_LIMIT - 1) begin
            cnt72 <= 0;
        end
        else begin
            cnt72 <= cnt72 + 1;
        end
    end
    assign led[0] = cnt50[31];
    assign led[1] = cnt72[31];
    assign pmod = cnt72[7:0];
endmodule

