module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [31:0] counter;
    reg [31:0] index;
    reg [9:0] keypress_array [0:10];
    initial begin
        keypress_array[0] = 10'b0000000000;
        keypress_array[1] = 10'b0000000001;
        keypress_array[2] = 10'b0000000010;
        keypress_array[3] = 10'b0000000011;
        keypress_array[4] = 10'b0000000100;
        keypress_array[5] = 10'b0000000101;
        keypress_array[6] = 10'b0000000110;
        keypress_array[7] = 10'b0000000111;
        keypress_array[8] = 10'b0000001000;
        keypress_array[9] = 10'b0000001001;
    end
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end
        else begin
            if (counter == 20) begin
                keypress <= keypress_array[index];
                counter <= 0;
                if (index == 9) begin
                    index <= 0;
                end
                else begin
                    index <= index + 1;
                end
            end
            else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

