parameter [31:0] H_ACTIVE_END=639;
parameter [31:0] V_ACTIVE_END=479;
reg [9:0] h_counter = 0;
reg [9:0] v_counter = 0;
  assign hsync = (h_counter < H_SYNC_START) ? 1'b0 : 1'b1;
  assign vsync = (v_counter < V_SYNC_START) ? 1'b0 : 1'b1;
  assign pixel_x = h_counter;
  assign pixel_y = v_counter;
  assign visible_region = (h_counter >= H_ACTIVE_START) && (h_counter <= H_ACTIVE_END) && (v_counter >= V_ACTIVE_START) && (v_counter <= V_ACTIVE_END) ? 1'b1 : 1'b0;
  always @(posedge pixel_clk) begin
    if((h_counter == H_SYNC_END) || (h_counter == H_SYNC_BLANK)) begin
      h_counter <= 0;
      if((v_counter == V_SYNC_END) || (v_counter == V_SYNC_BLANK)) begin
        v_counter <= 0;
      end
      else begin
        v_counter <= v_counter + 1;
      end
    end
    else begin
      h_counter <= h_counter + 1;
    end
  end
endmodule

