assign read_pc = pc;
assign read_ccr = ccr;

always @(posedge clk)
begin
	if(rst)
	begin
		for (int i = 0; i < REG_NUMBER; i = i + 1)
		begin
			reg_file[i] = 0;
		end
		pc = 32'b00000000000000000000000000000000;
		sp = 32'b00000000000000000000000000000011;
		ccr = 32'b00000000000000000000000000000000;
	end
	else
	begin
		if(Data_write1)
		begin
			reg_file[write_addr1] = write_data1;
		end
		if(sp_write)
		begin
			sp = write_sp_data;
		end
		pc = {write_pc_data[31:24],write_pc_data[23:0]};
		ccr = write_ccr;
	end
end
