    count <= count + 1;
    if(count == 2'b11) begin
      count <= 2'b00;
    end
    if(count == 2'b01) begin
      clk_o <= 1'b1;
    end
    else if(count == 2'b10) begin
      clk_o <= 1'b1;
    end
    else begin
      clk_o <= 1'b0;
    end
  end
  assign count_o = count;
endmodule

