module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
over_time, over_weight, weight_alert, door_alert, out_current_floor) ;


input [7:0]request_floor; 
input [7:0]in_current_floor; 
input clk; 
input reset; 
input over_time; 
input over_weight; 



output direction; 
output complete;
output door_alert;
output weight_alert;
output [7:0] out_current_floor;
reg [7:0] out_current_floor; 
reg direction; 
reg complete; 
reg door_alert; 
reg weight_alert; 
reg [7:0] current_floor; 
reg [7:0] request_floor; 
reg [7:0] in_current_floor; 
reg clk; 
reg reset; 
reg over_time; 
reg over_weight; 



always @(posedge clk) begin
	if (reset == 1) begin
		out_current_floor <= in_current_floor; 
		current_floor <= in_current_floor; 
		complete <= 0; 
		direction <= 0; 
		door_alert <= 0; 
		weight_alert <= 0; 
	end
	else if (request_floor == current_floor) begin
		complete <= 1; 
		direction <= 0; 
		door_alert <= 0; 
		weight_alert <= 0; 
	end
	else if (request_floor > current_floor) begin
		current_floor <= current_floor + 1; 
		direction <= 1; 
		complete <= 0; 
		door_alert <= 0; 
		weight_alert <= 0; 
	end
	else if (request_floor < current_floor) begin
		current_floor <= current_floor - 1; 
		direction <= 0; 
		complete <= 0; 
		door_alert <= 0; 
		weight_alert <= 0; 
	end
	else if (over_time == 1) begin
		door_alert <= 1; 
		complete <= 0; 
		direction <= 0; 
		weight_alert <= 0; 
	end
	else if (over_weight == 1) begin
		weight_alert <= 1; 
		complete <= 0; 
		direction <= 0; 
		door_alert <= 0; 
	end
end

endmodule

