module shift_16_9 (
    input [15:0] x,
    input [15:0] y,
    input [1:0] shiftAlufn,
    output reg [15:0] shiftOut
  );
reg [15:0] temp;
  always @* begin
    case (shiftAlufn)
      2'b00: begin
        temp = x << y[3:0];
      end
      2'b01: begin
        temp = x >> y[3:0];
      end
      2'b10: begin
        temp = $signed(x) >>> y[3:0];
      end
      2'b11: begin
        temp = $signed(x) << y[3:0];
      end
      default: begin
        temp = 0;
      end
    endcase
    shiftOut = temp;
  end
endmodule

module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0]
  reset = 0,
  idle = 1,
  running = 2,
  complete = 3;
reg [1:0] current_state = reset;  
reg [1:0] next_state = reset;  
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      current_state <= reset;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    reset : begin
      done <= 1'b0;
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      if(go == 1'b1) begin
        next_state <= idle;
      end
      else begin
        next_state <= reset;
      end
    end
    idle : begin
      done <= 1'b0;
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      if(go == 1'b1) begin
        next_state <= running;
      end
      else begin
        next_state <= idle;
      end
    end
    running : begin
      done <= 1'b0;
      WVALID <= 1'b1;
      WSTRB <= 4'b1111;
      WDATA <= data;
      if(WREADY == 1'b1) begin
        next_state <= complete;
      end
      else begin
        next_state <= running;
      end
    end
    complete : begin
      done <= 1'b1;
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      if(go == 1'b1) begin
        next_state <= idle;
      end
      else begin
        next_state <= complete;
      end
    end
    default : begin
      done <= 1'b0;
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      next_state <= reset;
    end
    endcase
  end
endmodule

