  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  assign io_ready = (state == 4'b0001);
  assign tx = (state == 4'b0000) ? 1'b1 : data[0];
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'b0000;
      data <= 8'b00000000;
    end else begin
      if (tick) begin
        if (io_valid) begin
          if (state == 4'b0000) begin
            data <= io_bits;
            state <= 4'b0001;
          end else if (state == 4'b0001) begin
            state <= 4'b0010;
          end else if (state == 4'b0010) begin
            state <= 4'b0011;
          end else if (state == 4'b0011) begin
            state <= 4'b0100;
          end else if (state == 4'b0100) begin
            state <= 4'b0101;
          end else if (state == 4'b0101) begin
            state <= 4'b0110;
          end else if (state == 4'b0110) begin
            state <= 4'b0111;
          end else if (state == 4'b0111) begin
            state <= 4'b1000;
          end else if (state == 4'b1000) begin
            state <= 4'b0000;
          end
        end
        if (state != 4'b0000) begin
          data <= data >> 1;
        end
      end
    end
  end
endmodule

