reg clk_filter = 1'b0;  
reg [7:0] shift_reg = 8'b0;  
reg timeout = 1'b0;  
  always @(posedge clk) begin
    if((clk_filter == 1'b0)) begin
      clk_filter <= 1'b1;
      if((kbd_clk == 1'b1)) begin
        if((timeout == 1'b0)) begin
          if((bitsCount == 0)) begin
            shift_reg <= {shift_reg[6:0],kbd_dat};
            bitsCount <= bitsCount + 1;
          end
          else begin
            if((bitsCount < 8)) begin
              shift_reg <= {shift_reg[6:0],kbd_dat};
              bitsCount <= bitsCount + 1;
            end
            else begin
              if((bitsCount == 8)) begin
                shift_reg <= {shift_reg[6:0],kbd_dat};
                bitsCount <= bitsCount + 1;
                timeout <= 1'b1;
              end
            end
          end
        end
        else begin
          if((bitsCount == 8)) begin
            timeout <= 1'b0;
            bitsCount <= 0;
            interrupt <= 1'b1;
            scanCode <= shift_reg;
          end
        end
      end
    end
    else begin
      clk_filter <= 1'b0;
    end
  end
