module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] H_TOTAL_PIXELS=1280 + 16 + 96;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] V_TOTAL_LINES=720 + 10 + 2;
reg [10:0] X_reg;
reg [10:0] Y_reg;
reg H_SYNC_reg;
reg V_SYNC_reg;
reg DISP_EN_reg;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      X_reg <= 0;
      Y_reg <= 0;
      H_SYNC_reg <= 1'b1;
      V_SYNC_reg <= 1'b1;
      DISP_EN_reg <= 1'b0;
    end else begin
      if((X_reg == (H_TOTAL_PIXELS - 1))) begin
        X_reg <= 0;
        if((Y_reg == (V_TOTAL_LINES - 1))) begin
          Y_reg <= 0;
        end
        else begin
          Y_reg <= Y_reg + 1;
        end
      end
      else begin
        X_reg <= X_reg + 1;
      end
      if((X_reg < (H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE))) begin
        H_SYNC_reg <= 1'b0;
      end
      else begin
        H_SYNC_reg <= 1'b1;
      end
      if((Y_reg < (V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE))) begin
        V_SYNC_reg <= 1'b0;
      end
      else begin
        V_SYNC_reg <= 1'b1;
      end
      if((X_reg < H_ACTIVE) && (Y_reg < V_ACTIVE)) begin
        DISP_EN_reg <= 1'b1;
      end
      else begin
        DISP_EN_reg <= 1'b0;
      end
    end
  end
  assign H_SYNC = H_SYNC_reg;
  assign V_SYNC = V_SYNC_reg;
  assign X = X_reg;
  assign Y = Y_reg;
  assign DISP_EN = DISP_EN_reg;
endmodule

