module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    reg ready;
    always @(negedge i_clock or posedge reset) begin
        if (reset) begin
            scan_code <= 8'b0;
            counter <= 4'b0;
            ready <= 1'b0;
        end else begin
            if (counter == 4'b1000) begin
                ready <= 1'b1;
                counter <= 4'b0;
            end else begin
                ready <= 1'b0;
                scan_code[counter] <= i_data;
                counter <= counter + 1'b1;
            end
        end
    end
    assign scan_ready = ready;
    assign scan_code = scan_code;
endmodule

