module Mapper66(input clk, input ce, input reset,
                input [31:0] flags,
                input [15:0] prg_ain, output [21:0] prg_aout,
                input prg_read, prg_write,                   
                input [7:0] prg_din,
                output prg_allow,                            
                input [13:0] chr_ain, output [21:0] chr_aout,
                output chr_allow,                      
                output vram_a10,                             
                output vram_ce);
reg [15:0] prg_bank;
    reg [15:0] chr_bank;
    reg [15:0] prg_aout_tmp;
    reg [21:0] chr_aout_tmp;
    reg prg_allow_tmp;
    reg chr_allow_tmp;
    reg vram_a10_tmp;
    reg vram_ce_tmp;
    assign prg_aout = prg_aout_tmp;
    assign chr_aout = chr_aout_tmp;
    assign prg_allow = prg_allow_tmp;
    assign chr_allow = chr_allow_tmp;
    assign vram_a10 = vram_a10_tmp;
    assign vram_ce = vram_ce_tmp;
    always @(posedge clk) begin
        if (reset) begin
            prg_bank <= 0;
            chr_bank <= 0;
            prg_aout_tmp <= 0;
            chr_aout_tmp <= 0;
            prg_allow_tmp <= 0;
            chr_allow_tmp <= 0;
            vram_a10_tmp <= 0;
            vram_ce_tmp <= 0;
        end
        else begin
            if (ce) begin
                if (prg_write) begin
                    if (prg_ain[15:14] == 2'b00) begin
                        prg_bank <= prg_din;
                        prg_allow_tmp <= 1;
                    end
                    else begin
                        prg_allow_tmp <= 0;
                    end
                end
                else begin
                    prg_allow_tmp <= 0;
                end
                if (chr_write) begin
                    if (chr_ain[15:14] == 2'b00) begin
                        chr_bank <= prg_din;
                        chr_allow_tmp <= 1;
                    end
                    else begin
                        chr_allow_tmp <= 0;
                    end
                end
                else begin
                    chr_allow_tmp <= 0;
                end
                if (flags[1]) begin
                    vram_a10_tmp <= 1;
                    vram_ce_tmp <= 1;
                end
                else begin
                    vram_a10_tmp <= 0;
                    vram_ce_tmp <= 0;
                end
            end
            else begin
                prg_allow_tmp <= 0;
                chr_allow_tmp <= 0;
                vram_a10_tmp <= 0;
                vram_ce_tmp <= 0;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            prg_aout_tmp <= 0;
            chr_aout_tmp <= 0;
        end
        else begin
            if (ce) begin
                prg_aout_tmp <= prg_ain + prg_bank;
                chr_aout_tmp <= chr_ain + chr_bank;
            end
        end
    end
endmodule

