input [31:0] address1, address2;

input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [64*16-1:0] datainmem;
reg [64*16-1:0] dataoutmem;
reg [64*16-1:0] datamem[0:2**31-1];

always @(posedge clk) begin
    if (rst) begin
        datainmem <= 0;
        dataoutmem <= 0;
        datamem[address1] <= 0;
        datamem[address2] <= 0;
    end
    else begin
        if (wren) begin
            datamem[address1] <= datain;
            datamem[address1+inputsize] <= datain;
            datamem[address1+2*inputsize] <= datain;
            datamem[address1+3*inputsize] <= datain;
            datamem[address1+4*inputsize] <= datain;
            datamem[address1+5*inputsize] <= datain;
            datamem[address1+6*inputsize] <= datain;
            datamem[address1+7*inputsize] <= datain;
            datamem[address1+8*inputsize] <= datain;
            datamem[address1+9*inputsize] <= datain;
