            datamem[address1+11*inputsize] <= datain;
            datamem[address1+12*inputsize] <= datain;
            datamem[address1+13*inputsize] <= datain;
            datamem[address1+14*inputsize] <= datain;
            datamem[address1+15*inputsize] <= datain;
        end
        if (rden) begin
            dataout <= datamem[address2];
        end
    end
end

always @(datain) begin
    datainmem <= datain;
end

always @(datainmem) begin
