  input signed [ACCUM_WIDTH-1:0] sample_accum,   
  output signed [OUT_WIDTH-1:0] sample_out       
);
reg signed [IN_WIDTH-1:0] a_reg;
  reg signed [IN_WIDTH-1:0] b_reg;
  reg signed [IN_WIDTH-1:0] ad_reg;
  reg signed [COEFF_WIDTH-1:0] m_reg;
  reg signed [ACCUM_WIDTH-1:0] p_reg;
  reg signed [COEFF_WIDTH-1:0] coeff_reg;
  reg signed [ACCUM_WIDTH-1:0] sample_accum_reg;
  always @(posedge clk) begin
    if (clear) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
      coeff_reg <= 0;
      sample_accum_reg <= 0;
    end
    else if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
      coeff_reg <= 0;
      sample_accum_reg <= 0;
    end
