module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 125000000;
  parameter UART_BPS = 115200;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  reg tx_flag;
  reg [7:0] tx_data;
  reg [31:0] clk_cnt;
  reg [3:0] tx_cnt;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= 0;
      tx_data <= 0;
      clk_cnt <= 0;
      tx_cnt <= 0;
      uart_txd <= 0;
    end else begin
      if (uart_en) begin
        tx_flag <= 1;
        tx_data <= uart_din;
        clk_cnt <= 0;
        tx_cnt <= 0;
        uart_txd <= 1;
      end else begin
        if (tx_flag) begin
          if (clk_cnt == BPS_CNT) begin
            if (tx_cnt == 0) begin
              uart_txd <= 0;
            end else if (tx_cnt == 4'd7) begin
              uart_txd <= tx_data[7];
            end else begin
              uart_txd <= tx_data[tx_cnt - 1];
            end
            if (tx_cnt == 4'd7) begin
              tx_flag <= 0;
            end
            tx_cnt <= tx_cnt + 1;
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end
      end
    end
  end
endmodule

