module boardSynchroniser(
    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );
reg synch = 1'b0;
    reg lastToggle = 1'b0;
    reg lastSynch = 1'b0;
    reg lastOpMode = 1'b0;
    reg lastSynchroStatus = 1'b0;
    always @(posedge clk) begin
        lastToggle <= toggle_en;
        lastSynch <= synch;
        lastOpMode <= opMode;
        lastSynchroStatus <= synchroStatus;
        if (lastToggle == 1'b1 && toggle_en == 1'b0) begin
            if (synch == 1'b0) begin
                synch <= 1'b1;
            end
            else begin
                synch <= 1'b0;
            end
        end
        if (synch == 1'b1) begin
            if (synchroStatus == 1'b0) begin
                synchroStatus <= 1'b1;
            end
        end
        else begin
            if (synchroStatus == 1'b1) begin
                synchroStatus <= 1'b0;
            end
        end
        if (opMode == 1'b1) begin
            syncInOut <= synch;
        end
        else begin
            syncInOut <= 1'bx;
        end
    end
endmodule

