module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
generate
    if (ASYNC == 0) begin
        reg [DATA_WIDTH-1:0] dout_reg;
        always @(din or clk) begin
            if (DATA_TYPE == "unsigned") begin
                dout_reg <= din << SHIFT_VALUE;
            end else begin
                dout_reg <= din >> SHIFT_VALUE;
            end
        end
        assign dout = dout_reg;
    end else begin
        wire [DATA_WIDTH-1:0] dout_wire;
        assign dout_wire = din << SHIFT_VALUE;
        assign dout = dout_wire;
    end
    if (DATA_TYPE == "unsigned") begin
        if (OVERFLOW_WARNING == 1) begin
            assign warning = (din >> (DATA_WIDTH-1)) & (din << (DATA_WIDTH-1));
        end else begin
            assign warning = 0;
        end
    end else begin
        if (OVERFLOW_WARNING == 1) begin
            assign warning = (din > 0) & (din << (DATA_WIDTH-1));
        end else begin
            assign warning = 0;
        end
    end
endgenerate
endmodule

