module alu_32 (
  input_a,
  input_b,
  control,
  zero, 
  cout,
  err_overflow,
  err_invalid_control,
  result
); 

input wire [WORD_SIZE-1:0]	input_a;
input wire [WORD_SIZE-1:0]	input_b;
input wire [CONTROL_SIGNAL_SIZE-1:0]	control;
output wire       zero;
output reg	      cout;
output reg	      err_overflow;
output reg	      err_invalid_control;
output reg [WORD_SIZE-1:0]	result;
parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;
parameter AND = 3'b000;
parameter OR = 3'b001;
parameter ADD = 3'b010;
parameter ADD_UNSIGNED = 3'b011;
parameter SUB = 3'b100;
parameter SLT = 3'b101;
parameter NOR = 3'b110;

assign zero = (result == 0);

always @(*) begin
  case (control)
    AND: begin
      result = input_a & input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    OR: begin
      result = input_a | input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    ADD: begin
      result = input_a + input_b;
      cout = (input_a[WORD_SIZE-1] ^ input_b[WORD_SIZE-1]) ^ result[WORD_SIZE-1];
      err_overflow = (input_a[WORD_SIZE-1] ^ input_b[WORD_SIZE-1]) ^ result[WORD_SIZE-1];
      err_invalid_control = 0;
    end
    ADD_UNSIGNED: begin
      result = input_a + input_b;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    SUB: begin
      result = input_a - input_b;
      cout = (input_a[WORD_SIZE-1] ^ input_b[WORD_SIZE-1]) ^ result[WORD_SIZE-1];
      err_overflow = (input_a[WORD_SIZE-1] ^ input_b[WORD_SIZE-1]) ^ result[WORD_SIZE-1];
      err_invalid_control = 0;
    end
    SLT: begin
      result = (input_a < input_b) ? 1 : 0;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    NOR: begin
      result = ~(input_a | input_b);
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 0;
    end
    default: begin
      result = 0;
      cout = 0;
      err_overflow = 0;
      err_invalid_control = 1;
    end
  endcase
end

endmodule

