    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
reg[31:0] x_var; 
    reg[31:0] y_var; 
    reg[31:0] u_var; 
    wire[31:0] temp; 
    assign Xoutport = x_var; 
    assign Youtport = y_var; 
    assign Uoutport = u_var; 
    always @(posedge CLK or negedge reset) begin
        if (reset == 0) begin
            x_var <= 0; 
            y_var <= 0; 
            u_var <= 0; 
        end
        else begin
            x_var <= x_var + DXport; 
            y_var <= y_var + (DXport * u_var); 
            u_var <= u_var + (DXport * (y_var - (x_var * x_var)); 
            if (x_var >= Aport) begin
                x_var <= 0; 
                y_var <= 0; 
                u_var <= 0; 
            end
        end
    end
endmodule

