module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] cnt;
    always @(posedge clk or negedge reset)
    begin
        if(!reset)
            cnt <= 0;
        else
            cnt <= cnt + 1;
    end
    always @*
    begin
        case(cnt)
            0: begin
                en <= 4'b1110;
                sseg <= hex0;
            end
            1: begin
                en <= 4'b1101;
                sseg <= hex1;
            end
            2: begin
                en <= 4'b1011;
                sseg <= hex2;
            end
            3: begin
                en <= 4'b0111;
                sseg <= hex3;
            end
            default: begin
                en <= 4'b0000;
                sseg <= 8'b00000000;
            end
        endcase
    end
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    assign tmp = {{3{data_i[13]}},data_i};
    always @(*) begin
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = tmp << 1;
            2'b10: data_o = tmp << 2;
            2'b11: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @(a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] data [31:0];
integer i;
initial begin
    for (i = 0; i < 32; i = i + 1) begin
        data[i] = 0;
    end
end
always @(posedge clk) begin
    if (MemWrite == 1) begin
        data[addr] = write_data;
    end
end
assign read_data = (MemRead == 1) ? data[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign out = cnt;
    assign enable_wires[0] = ena;
    assign ovf = (cnt == 0) ^ updown;
    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : gen_loop
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else begin
                    if (enable_wires[i]) begin
                        if (updown) begin
                            cnt[i] <= cnt[i] + 1;
                        end else begin
                            cnt[i] <= cnt[i] - 1;
                        end
                    end
                end
            end
            assign enable_wires[i + 1] = enable_wires[i] & (cnt[i] != 0);
        end
    endgenerate
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] bcd;
		integer i;
		assign b = bcd[3:0];
		assign s = bcd[7:4];
		assign g = bcd[11:8];
		assign q = bcd[15:12];
		always @ (binary)
		begin
			bcd = 0;
			for (i = 0; i < 16; i = i + 1)
			begin
				bcd = bcd << 4;
				bcd[3:0] = binary[3:0];
				if (bcd[3:0] > 4)
					bcd[3:0] = bcd[3:0] + 3;
				binary = binary >> 4;
			end
			bcd = bcd >> 4;
		end
endmodule

module risc_v_32_mem(m_addr,d_f_mem,inst_decode,mem_out);
input  [31:0] m_addr;                                    
    input  [31:0] d_f_mem;                                   
    input  [36:0] inst_decode;								 
	output reg [31:0] mem_out;
wire [31:0] mem_out_tmp;
	assign mem_out_tmp = d_f_mem;
	always @(*) begin
		if(inst_decode[36:35]==2'b00) begin
			mem_out = mem_out_tmp;
		end
		else if(inst_decode[36:35]==2'b01) begin
			if(m_addr[1:0]==2'b00) begin
				mem_out = mem_out_tmp;
			end
			else if(m_addr[1:0]==2'b01) begin
				mem_out = mem_out_tmp[31:0];
			end
			else if(m_addr[1:0]==2'b10) begin
				mem_out = mem_out_tmp[31:0];
			end
			else if(m_addr[1:0]==2'b11) begin
				mem_out = mem_out_tmp[31:0];
			end
		end
		else if(inst_decode[36:35]==2'b10) begin
			if(m_addr[1:0]==2'b00) begin
				mem_out = mem_out_tmp;
			end
			else if(m_addr[1:0]==2'b01) begin
				mem_out = mem_out_tmp[31:0];
			end
			else if(m_addr[1:0]==2'b10) begin
				mem_out = mem_out_tmp[31:0];
			end
			else if(m_addr[1:0]==2'b11) begin
				mem_out = mem_out_tmp[31:0];
			end
		end
		else if(inst_decode[36:35]==2'b11) begin
			if(m_addr[1:0]==2'b00) begin
				mem_out = mem_out_tmp;
			end
			else if(m_addr[1:0]==2'b01) begin
				mem_out = mem_out_tmp[31:0];
			end
			else if(m_addr[1:0]==2'b10) begin
				mem_out = mem_out_tmp[31:0];
			end
			else if(m_addr[1:0]==2'b11) begin
				mem_out = mem_out_tmp[31:0];
			end
		end
	end
endmodule

module Data_Memory 
#(	
	parameter DATA_WIDTH = 32,
	parameter MEMORY_DEPTH = 64
)
(
	input clk, Write_Enable_i, 
	input [DATA_WIDTH-1:0] Write_Data_i,
	input [DATA_WIDTH-1:0]  Address_i,
	output [(DATA_WIDTH-1):0]  Read_Data_o
);
reg [DATA_WIDTH-1:0] Var_i = 32'h10010000;
	reg [DATA_WIDTH-1:0] Data_Memory [0:MEMORY_DEPTH-1];

	assign Read_Data_o = Data_Memory[Address_i - Var_i >> 2];

	always @(posedge clk)
	begin
		if (Write_Enable_i)
			Data_Memory[Address_i - Var_i >> 2] <= Write_Data_i;
	end
endmodule

