module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] Registers [31:0];
    always @(negedge Clk)
    begin
        if (ReadReg1 == 0)
            ReadData1 <= 0;
        else
            ReadData1 <= Registers[ReadReg1];
        if (ReadReg2 == 0)
            ReadData2 <= 0;
        else
            ReadData2 <= Registers[ReadReg2];
    end
    always @(posedge Clk)
    begin
        if (RegWrite)
            Registers[WriteReg] <= WriteData;
    end
endmodule

module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 1.0;
    parameter C_L = 1.0;
    parameter t_hmin = 1.0;
    parameter t_hmax = 1.0;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR == 1'b1) begin
            Q <= D;
            counter = counter + 1;
        end
        else begin
            Q <= 1'b0;
            counter = 0;
        end
    end
    always @(Q) begin
        $display("Pd = %d * %f * %f^2 = %f", counter, C_L, Vcc, counter * C_L * Vcc * Vcc);
    end
endmodule

