module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);


input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
parameter INIT = 0;

reg [DATA_WIDTH-1:0]            mem [2**ADDR_WIDTH-1:0];
reg [DATA_WIDTH-1:0]            dout_r;
reg                             we_r;
reg [ADDR_WIDTH-1:0]            waddr_r;
reg [DATA_WIDTH-1:0]            din_r;

initial begin
    if (CLEAR_ON_INIT) begin
        for (int i = 0; i < 2**ADDR_WIDTH; i++) begin
            mem[i] = INIT;
        end
    end
end

always @(*) begin
    if (ENABLE_BYPASS && we_r && (waddr_r == raddr)) begin
        dout_r = din_r;
    end else begin
        dout_r = mem[waddr_r];
    end
end

always @(posedge clk) begin
    if (we) begin
        mem[waddr] <= din;
    end
    we_r <= we;
    waddr_r <= waddr;
    din_r <= din;
end

assign dout = dout_r;

endmodule

