module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam IDLE = 2'b00;
  localparam READY = 2'b01;
  localparam RELEASE = 2'b10;

  reg [1:0] state = IDLE;
  reg [23:0] r_count = 0;
  reg [23:0] r_ppfifo_size = 0;

  always @(posedge clk) begin
    if (rst) begin
      o_ppfifo_clk <= 1'b0;
      o_ppfifo_act <= 2'b00;
      o_ppfifo_stb <= 1'b0;
      o_ppfifo_data <= {DATA_WIDTH{1'b0}};
      r_count <= 0;
      r_ppfifo_size <= 0;
      state <= IDLE;
    end
    else begin
      o_ppfifo_clk <= clk;
      o_ppfifo_stb <= 1'b0;
      o_ppfifo_data <= {DATA_WIDTH{1'b0}};
      case (state)
        IDLE: begin
          if (i_ppfifo_rdy == 2'b11) begin
            o_ppfifo_act <= 2'b11;
            state <= READY;
          end
        end
        READY: begin
          if (i_h_blank == 1'b0) begin
            if (r_count < i_ppfifo_size) begin
              o_ppfifo_stb <= 1'b1;
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end
            else begin
              state <= RELEASE;
            end
          end
        end
        RELEASE: begin
          o_ppfifo_act <= 2'b00;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

