module matrix5arb (
   		   input clk,
   		   input rst_n,
   		   input [4:0] req,
   		   output [4:0] grant
   		   );
reg [4:0] state;
   reg [4:0] next_state;
   reg [4:0] next_grant;
   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
	 state <= 5'b0;
	 next_state <= 5'b0;
	 next_grant <= 5'b0;
      end
      else begin
	 state <= next_state;
	 next_state <= next_state;
	 next_grant <= next_grant;
      end
   end
   always @(*) begin
      next_state = state;
      next_grant = 5'b0;
      if (req[0]) begin
	 next_grant[0] = 1'b1;
	 next_state = 5'b0;
      end
      else if (req[1]) begin
	 next_grant[1] = 1'b1;
	 next_state = 5'b0;
      end
      else if (req[2]) begin
	 next_grant[2] = 1'b1;
	 next_state = 5'b0;
      end
      else if (req[3]) begin
	 next_grant[3] = 1'b1;
	 next_state = 5'b0;
      end
      else if (req[4]) begin
	 next_grant[4] = 1'b1;
	 next_state = 5'b0;
      end
      else begin
	 next_state = state;
	 next_grant = 5'b0;
      end
   end
   assign grant = state;
endmodule

module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
 parameter INSERT_REGISTER = 0;

 reg [DATA_WIDTH-1:0] datain;
 reg datain_valid;
 reg datain_stall;
 reg dataout_stall;
 reg dataout_valid;

 always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
   datain <= 0;
   datain_valid <= 0;
   datain_stall <= 0;
   dataout_stall <= 0;
   dataout_valid <= 0;
  end
  else begin
   datain <= i_datain;
   datain_valid <= i_datain_valid;
   datain_stall <= o_datain_stall;
   dataout_stall <= i_dataout_stall;
   dataout_valid <= o_dataout_valid;
  end
 end

 always @(datain or datain_valid or datain_stall or dataout_stall or dataout_valid) begin
  if (INSERT_REGISTER == 1) begin
   if (datain_stall == 1'b0) begin
    o_datain_stall <= 1'b0;
    o_dataout <= datain;
    o_dataout_valid <= datain_valid;
   end
   else begin
    o_datain_stall <= 1'b1;
    o_dataout <= 0;
    o_dataout_valid <= 1'b0;
   end
  end
  else begin
   o_datain_stall <= 1'b0;
   o_dataout <= datain;
   o_dataout_valid <= datain_valid;
  end
 end

endmodule

