module display(
    input sysclk,
    input [7:0] anodes,
    output reg shift = 0,
    output reg latch = 0,
    output reg data = 0
    );
reg [3:0] step_count = 0;
    reg [7:0] old_anodes = 0;
    always @(posedge sysclk) begin
        if (anodes != old_anodes) begin
            step_count <= 0;
            old_anodes <= anodes;
        end
        if (step_count == 0) begin
            latch <= 0;
            shift <= 1;
            data <= anodes[7];
        end
        else if (step_count == 1) begin
            latch <= 1;
            shift <= 0;
            data <= anodes[6];
        end
        else if (step_count == 2) begin
            latch <= 0;
            shift <= 1;
            data <= anodes[5];
        end
        else if (step_count == 3) begin
            latch <= 1;
            shift <= 0;
            data <= anodes[4];
        end
        else if (step_count == 4) begin
            latch <= 0;
            shift <= 1;
            data <= anodes[3];
        end
        else if (step_count == 5) begin
            latch <= 1;
            shift <= 0;
            data <= anodes[2];
        end
        else if (step_count == 6) begin
            latch <= 0;
            shift <= 1;
            data <= anodes[1];
        end
        else if (step_count == 7) begin
            latch <= 1;
            shift <= 0;
            data <= anodes[0];
        end
        else if (step_count == 8) begin
            latch <= 0;
            shift <= 1;
            data <= 0;
        end
        else if (step_count == 9) begin
            latch <= 1;
            shift <= 0;
            data <= 0;
        end
        step_count <= step_count + 1;
    end
endmodule

