module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
    );
parameter S1 = 3'b000;
    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;

