        if (!rst_n) begin
            state <= S1;
        end else begin
            state <= next;
        end
    end

    always @(*) begin
        case (state)
            S1: begin
                if (x == 1'b0) begin
                    next = S2;
                end else begin
                    next = S1;
                end
            end
            S2: begin
                if (x == 1'b0) begin
                    next = S3;
                end else begin
                    next = S1;
                end
            end
            S3: begin
                if (x == 1'b0) begin
                    next = S4;
                end else begin
                    next = S1;
                end
            end
            S4: begin
                if (x == 1'b0) begin
                    next = S5;
                end else begin
                    next = S1;
                end
            end
            S5: begin
                if (x == 1'b0) begin
                    next = S6;
                end else begin
                    next = S1;
                end
            end
            S6: begin
                if (x == 1'b0) begin
                    next = S1;
