module lfsr24(
input wire Clk,
input wire one,
input wire tick,
input wire [6:0] coreCount,
output reg data
); 

reg [23:0] lfsr_p; reg [23:0] lfsr_n;
  always @(posedge Clk, posedge one) begin
    if(one == 1'b1) begin
      lfsr_p <= 24'h020000;
    end else begin
      lfsr_p <= lfsr_n;
    end
  end
  always @(posedge tick) begin
    lfsr_n <= lfsr_p;
    if(coreCount < 24) begin
      lfsr_n <= {lfsr_p[22:0],lfsr_p[23]};
    end
    else begin
      lfsr_n <= {lfsr_p[21:0],lfsr_p[23:22]};
    end
  end
  always @(lfsr_p) begin
    if(coreCount < 24) begin
      data <= lfsr_p[23];
    end
    else begin
      data <= lfsr_p[22];
    end
  end
endmodule

