module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000000;


  reg [31:0] M_x, M_y, M_z, M_w, M_w_d;
  wire [31:0] M_x_q, M_y_q, M_z_q, M_w_q;
  wire [31:0] t;


  assign M_x_q = M_x;
  assign M_y_q = M_y;
  assign M_z_q = M_z;
  assign M_w_q = M_w;
  assign t = M_x_q ^ (M_x_q << 13);


  always @(posedge clk) begin
    if (rst) begin
      M_w_d = SEED ^ seed;
      M_x <= M_w_d;
      M_y <= M_w_d;
      M_z <= M_w_d;
      M_w <= M_w_d;
    end
    else begin
      M_x <= M_y;
      M_y <= M_z;
      M_z <= M_w;
      M_w <= M_w_q;
    end
    if (next) begin
      M_w <= M_w_q;
    end
  end

  always @(*) begin
    M_w_d = M_x_q ^ (M_x_q << 13);
    M_w <= M_w_d ^ (M_w_d << 17);
    M_w <= M_w ^ (M_w << 5);
  end

  always @(posedge clk) begin
    num <= M_w_q;
  end

endmodule

