module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [1:0] current_state, next_state;


always @(posedge clk or posedge reset)
begin
	if(reset)
		current_state <= 0;
	else
		current_state <= next_state;
end

always @(*)
begin
	case(current_state)
		0: next_state = 1;
		1: next_state = 2;
		2: next_state = 3;
		3: next_state = 0;
		default: next_state = 0;
	endcase
end

assign red = (current_state == 0) ? 1 : 0;
assign yellow = (current_state == 0 || current_state == 3) ? 1 : 0;
assign green = (current_state == 1 || current_state == 2) ? 1 : 0;

endmodule

