module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;
    parameter lpm_type = "lpm_or";
    parameter lpm_hint = "UNUSED";


    reg    [lpm_width-1:0] result_tmp;


    integer i;
    integer j;


    initial
    begin
        if (lpm_width <= 0)
        begin
            $display("Value of lpm_width parameter must be greater than 0(ERROR)");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end
        if (lpm_size <= 0)
        begin
            $display("Value of lpm_size parameter must be greater than 0(ERROR)");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end
    end


    assign result = result_tmp;


    always @(data)
    begin
        result_tmp = 0;
        for (i = 0; i < lpm_size; i = i + 1)
        begin
            for (j = 0; j < lpm_width; j = j + 1)
            begin
                result_tmp[j] = result_tmp[j] | data[(i * lpm_width) + j];
            end
        end
    end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg [31:0] cnt;
    reg clk_div;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end
        else begin
            if (cnt == NUM_DIV/2 - 1) begin
                cnt <= 0;
                clk_div <= ~clk_div;
            end
            else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

