module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);
localparam BAUD = 9600;
localparam DIV = 100000000 / BAUD;
localparam IDLE = 0;
localparam START_BIT = 1;
localparam DATA_BITS = 2;
localparam PARITY_BIT = 3;
localparam STOP_BIT = 4;
localparam DATA_BITS_CNT = 8;
localparam PARITY_BIT_CNT = 9;
localparam STOP_BIT_CNT = 10;
reg [3:0] state;
reg [3:0] bit_counter;
reg [7:0] shift_reg;
reg parity_bit;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        bit_counter <= 0;
        shift_reg <= 0;
        parity_bit <= 0;
        done <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= START_BIT;
                    bit_counter <= 0;
                    shift_reg <= {1'b0, data_in};
                    parity_bit <= ^data_in;
                    done <= 0;
                end
            end
            START_BIT: begin
                if (bit_counter == 0) begin
                    state <= DATA_BITS;
                    bit_counter <= 0;
                end
            end
            DATA_BITS: begin
                if (bit_counter == DATA_BITS_CNT - 1) begin
                    state <= PARITY_BIT;
                    bit_counter <= 0;
                end
            end
            PARITY_BIT: begin
                if (bit_counter == PARITY_BIT_CNT - 1) begin
                    state <= STOP_BIT;
                    bit_counter <= 0;
                end
            end
            STOP_BIT: begin
                if (bit_counter == STOP_BIT_CNT - 1) begin
                    state <= IDLE;
                    bit_counter <= 0;
                    done <= 1;
                end
            end
        endcase
        if (state != IDLE) begin
            bit_counter <= bit_counter + 1;
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
        end
    end
end
endmodule

