module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
localparam STATE_LOAD_DATA = 0;
	localparam STATE_TRIGGER = 1;
	localparam STATE_POLL_BUSY = 2;
	localparam STATE_PAUSE = 3;
	localparam STATE_DONE = 4;
	localparam MSG_DELAY = 100000000;
	reg [1:0] state;
	reg [3:0] data_pos;
	reg [31:0] delay;
	always @(posedge clk_50M) begin
		if (run_test_raw) begin
			if (state == STATE_DONE) begin
				state <= STATE_LOAD_DATA;
				data_pos <= 0;
				delay <= 0;
			end
			else begin
				case (state)
					STATE_LOAD_DATA: begin
						if (delay == 0) begin
							data_out <= "Hello World! ";
							trigger <= 1;
							delay <= 100000000;
						end
						else begin
							trigger <= 0;
							delay <= delay - 1;
						end
					end
					STATE_TRIGGER: begin
						if (delay == 0) begin
							trigger <= 0;
							state <= STATE_POLL_BUSY;
							delay <= 100000000;
						end
						else begin
							trigger <= 0;
							delay <= delay - 1;
						end
					end
					STATE_POLL_BUSY: begin
						if (delay == 0) begin
							if (tx_busy) begin
								delay <= 100000000;
							end
							else begin
								state <= STATE_PAUSE;
								delay <= 100000000;
							end
						end
						else begin
							delay <= delay - 1;
						end
					end
					STATE_PAUSE: begin
						if (delay == 0) begin
							state <= STATE_DONE;
							delay <= 0;
						end
						else begin
							delay <= delay - 1;
						end
					end
					STATE_DONE: begin
						if (delay == 0) begin
							state <= STATE_LOAD_DATA;
							data_pos <= 0;
							delay <= 0;
						end
						else begin
							delay <= delay - 1;
						end
					end
				endcase
			end
		end
	end
endmodule

