module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [inputWidth-1:0] maxValue;
reg [inputWidth-1:0] inDataBuffer [(numInput*inputWidth)-1:0];
reg [31:0] counter;
always @(posedge i_clk)
begin
    if(i_valid)
    begin
        counter <= counter + 1;
        o_data_valid <= 0;
        maxValue <= inDataBuffer[(counter-1)*inputWidth+inputWidth-1:counter*inputWidth];
        o_data <= counter-1;
        for (int i = 0; i < numInput; i = i + 1)
        begin
            if (inDataBuffer[i*inputWidth+inputWidth-1:i*inputWidth] > maxValue)
            begin
                maxValue <= inDataBuffer[i*inputWidth+inputWidth-1:i*inputWidth];
                o_data <= i;
            end
        end
        o_data_valid <= 1;
    end
    else
    begin
        counter <= 0;
        o_data_valid <= 0;
    end
    for (int i = 0; i < numInput; i = i + 1)
    begin
        inDataBuffer[i*inputWidth+inputWidth-1:i*inputWidth] <= i_data[i*inputWidth+inputWidth-1:i*inputWidth];
    end
end
endmodule

