module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [1:0] state = 0;
reg [31:0] timeCount = 0;
reg [31:0] timeoutCounter = 0;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        state <= 0;
        timeCount <= 0;
        timeoutCounter <= 0;
        READY <= 0;
        sonar_trigger <= 0;
        inches <= 0;
    end
    else begin
        case(state)
            0: begin
                READY <= 0;
                if(do_measure) begin
                    state <= 1;
                    sonar_trigger <= 1;
                end
            end
            1: begin
                READY <= 0;
                if(sonar_pulse) begin
                    state <= 2;
                    timeCount <= 0;
                    timeoutCounter <= 0;
                end
            end
            2: begin
                READY <= 0;
                if(sonar_pulse) begin
                    timeCount <= timeCount + 1;
                    timeoutCounter <= timeoutCounter + 1;
                    if(timeoutCounter == 100000000) begin
                        state <= 0;
                        READY <= 1;
                        sonar_trigger <= 0;
                        inches <= 0;
                    end
                end
                else begin
                    state <= 0;
                    READY <= 1;
                    sonar_trigger <= 0;
                    inches <= 0;
                end
            end
            3: begin
                READY <= 0;
                if(sonar_pulse) begin
                    timeCount <= timeCount + 1;
                    timeoutCounter <= timeoutCounter + 1;
                    if(timeoutCounter == 100000000) begin
                        state <= 0;
                        READY <= 1;
                        sonar_trigger <= 0;
                        inches <= 0;
                    end
                end
                else begin
                    state <= 0;
                    READY <= 1;
                    sonar_trigger <= 0;
                    inches <= 0;
                end
            end
        endcase
    end
end
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        inches <= 0;
    end
    else begin
        if(READY) begin
            inches <= timeCount * 12 / 1000000;
        end
    end
end
endmodule

