    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);
localparam CONF_ADDR_BASE = 32'h00000000;
localparam CONF_ADDR_MASK = 32'h00000000;

reg sel_sram;
reg sel_conf;

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        sel_sram <= 1'b0;
        sel_conf <= 1'b0;
    end else begin
        sel_sram <= cpu_data_addr[31:29] == 3'b000;
        sel_conf <= cpu_data_addr[31:29] == 3'b001;
