module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    assign q_add = q_reg != 0;
    assign q_reset = q_reg == 0;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
        end else begin
            q_reg <= q_next;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            f1 <= 0;
            f2 <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            out <= 0;
        end else begin
            case ({q_add, q_reset})
                2'b01: out <= 0;
                2'b10: out <= f2;
                2'b11: out <= 0;
                default: out <= out;
            endcase
        end
    end
    reg [maxbit-1:0] q_add_reg, q_reset_reg;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_add_reg <= 0;
            q_reset_reg <= 0;
        end else begin
            q_add_reg <= q_add;
            q_reset_reg <= q_reset;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_next <= 0;
        end else begin
            q_next <= q_reg + q_add_reg;
        end
    end
endmodule

