	.clock   (negedge_vga_clk),
	.address (rom_address),
	.q       (rom_q)
);

Walk2_palette Walk2_palette (
	.index (rom_q),
	.red   (palette_red),
	.green (palette_green),
	.blue  (palette_blue)
);

endmodule

