module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30; 
parameter count = 4; 
reg [1:0]delay; 

top top1(clk,reset,rxD,s_in); 
assign s_in = sout[n-1:0]; 
always @(posedge clk or posedge reset) begin 
	if(reset) begin 
		sout <= 0; 
		counter <= 0; 
		signal <= 0; 
		delay <= 0; 
	end 
	else begin 
		if(counter == count) begin 
			delay <= 1; 
			signal <= 0; 
			counter <= 0; 
		end 
		else begin 
			sout <= {sout[n-2:0],s_in}; 
			counter <= counter + 1; 
			signal <= 0; 
			delay <= 0; 
		end 
	end 
end 
endmodule

