module testbench;
parameter GROUP_WIDTH = 4;
    parameter GROUP_COUNT = 2;

    reg [GROUP_COUNT * GROUP_WIDTH - 1:0] x;
    reg [GROUP_COUNT * GROUP_WIDTH - 1:0] y;
    reg carry_in;
