module twocmp(input [31:0]A,output [31:0]B);
genvar i;
generate
for(i=0;i<32;i=i+1)
begin
if(i==0)
begin
assign B[i]=A[i];
end
else
begin
assign B[i]=((|A[0:i-1])?(~A[i]):A[i]);
end
end
endgenerate
endmodule

