module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 32;
parameter SEL_WIDTH = 2;
parameter TOTAL_DAT = 32 * 2;

wire [DAT_WIDTH-1:0] dout;
wire [DAT_WIDTH-1:0] tmp [0:TOTAL_DAT/DAT_WIDTH-1];

genvar i,j;
generate
	for (i = 0; i < TOTAL_DAT/DAT_WIDTH; i = i + 1) begin
		for (j = 0; j < DAT_WIDTH; j = j + 1) begin
			assign tmp[i][j] = din[(i*DAT_WIDTH)+j];
		end
	end
endgenerate

assign dout = tmp[sel];

endmodule

