module TopModule(
    input clk,
    input areset,
    input in,
    output out
);
typedef enum logic [1:0] {
    A = 2'b00,
    B = 2'b01,
    C = 2'b10,
    D = 2'b11
} state_t;

state_t state, next_state;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        state <= A;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        A: begin
            if (in == 0) begin
                next_state = A;
            end else begin
                next_state = B;
            end
        end
        B: begin
            if (in == 0) begin
                next_state = C;
            end else begin
                next_state = B;
            end
        end
        C: begin
            if (in == 0) begin
                next_state = A;
            end else begin
                next_state = D;
            end
        end
        D: begin
            if (in == 0) begin
                next_state = C;
            end else begin
                next_state = B;
            end
        end
    endcase
end

assign out = (state == D);

endmodule

module TopModule(
