    input in,
    output out
);
reg [1:0] state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    state <= in ? 2'b01 : 2'b00;
                end
                2'b01: begin
                    state <= in ? 2'b10 : 2'b01;
                end
                2'b10: begin
                    state <= in ? 2'b11 : 2'b00;
                end
                2'b11: begin
                    state <= in ? 2'b01 : 2'b10;
                end
            endcase
        end
    end
    assign out = state[1];
endmodule

