            q <= data;
        end else begin
            q <= next(q);
        end
    end
    function [255:0] next(input [255:0] q);
        integer i, j;
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                integer count = 0;
                if (i > 0) begin
                    count = count + q[(i - 1) * 16 + j];
                end
                if (i < 15) begin
                    count = count + q[(i + 1) * 16 + j];
                end
                if (j > 0) begin
                    count = count + q[i * 16 + (j - 1)];
                end
                if (j < 15) begin
                    count = count + q[i * 16 + (j + 1)];
                end
                if (i > 0 && j > 0) begin
                    count = count + q[(i - 1) * 16 + (j - 1)];
                end
                if (i > 0 && j < 15) begin
                    count = count + q[(i - 1) * 16 + (j + 1)];
                end
                if (i < 15 && j > 0) begin
                    count = count + q[(i + 1) * 16 + (j - 1)];
                end
                if (i < 15 && j < 15) begin
                    count = count + q[(i + 1) * 16 + (j + 1)];
                end
                if (count == 0) begin
                    next[(i * 16) + j] = 0;
                end else if (count == 1) begin
                    next[(i * 16) + j] = 0;
                end else if (count == 2) begin
                    next[(i * 16) + j] = q[(i * 16) + j];
                end else if (count == 3) begin
                    next[(i * 16) + j] = 1;
                end else begin
                    next[(i * 16) + j] = 0;
                end
            end
        end
    endfunction
