module TopModule(
input wire clk,
input wire areset,
input wire bump_left,
input wire bump_right,
input wire ground,
input wire dig,
output reg walk_left,
output reg walk_right,
output reg aaah,
output reg digging
); 

always @(posedge clk, posedge areset) begin
    if((areset == 1'b1)) begin
      walk_left <= 1'b0;
      walk_right <= 1'b0;
      aaah <= 1'b0;
      digging <= 1'b0;
    end else begin
      if((ground == 1'b0)) begin
        aaah <= 1'b1;
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        digging <= 1'b0;
      end
      else if((dig == 1'b1)) begin
        digging <= 1'b1;
        aaah <= 1'b0;
        if((ground == 1'b1)) begin
          walk_left <= 1'b0;
          walk_right <= 1'b0;
        end
        else begin
          walk_left <= 1'b0;
          walk_right <= 1'b0;
        end
      end
      else if((bump_left == 1'b1)) begin
        walk_left <= 1'b0;
        walk_right <= 1'b1;
      end
      else if((bump_right == 1'b1)) begin
        walk_left <= 1'b1;
        walk_right <= 1'b0;
      end
      else begin
        walk_left <= 1'b0;
        walk_right <= 1'b0;
      end
    end
  end
endmodule

module TopModule(
    input clk,
    input reset,
    input data,
    output [3:0] count,
    output counting,
    output done,
    input ack
);
reg [3:0] delay;
    reg [3:0] count;
    reg counting;
    reg done;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
            delay <= 4'b0;
            counting <= 0;
            done <= 0;
        end
        else begin
            if (counting) begin
                count <= count + 1;
                if (count == (delay + 1) * 1000) begin
                    done <= 1;
                    counting <= 0;
                end
            end
            else begin
                if (data == 1 && count[0] == 0) begin
                    count <= 4'b0;
                    delay <= 4'b0;
                    counting <= 1;
                end
                else if (counting) begin
                    count <= {count[2:0], data};
                end
                else begin
                    count <= 4'b0;
                    delay <= 4'b0;
                    counting <= 0;
                    done <= 0;
                end
            end
        end
    end
endmodule

