module TopModule (
  input clk,
  input in,
  input reset,
  output [7:0] out_byte,
  output done
);
reg [7:0] out_byte;
  reg done;
  reg [3:0] state;
  reg [3:0] count;
  reg [3:0] expected;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      count <= 0;
      expected <= 0;
      done <= 0;
    end
    else begin
      case (state)
        0: begin
          if (in == 0) begin
            state <= 1;
            count <= 0;
            expected <= 8'hFF;
          end
        end
        1: begin
          if (count < 8) begin
            expected <= expected << 1;
            expected[0] <= in;
            count <= count + 1;
          end
          else begin
            state <= 2;
            count <= 0;
          end
        end
        2: begin
          if (in == 1) begin
            done <= 1;
            state <= 0;
          end
          else begin
            done <= 0;
            state <= 0;
          end
        end
      endcase
    end
  end
  assign out_byte = done ? expected : 8'hX;
endmodule

