    if (!resetn) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end
  always @(state or r) begin
    case (state)
      2'b00: begin
        if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
          next_state = 2'b00;
        end else if (r[0] == 1'b1) begin
          next_state = 2'b01;
        end else if (r[0] == 1'b0 && r[1] == 1'b1) begin
          next_state = 2'b10;
        end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
          next_state = 2'b11;
        end
      end
      2'b01: begin
        if (r[0] == 1'b1) begin
          next_state = 2'b01;
        end else if (r[0] == 1'b0 && r[1] == 1'b1) begin
          next_state = 2'b10;
        end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
          next_state = 2'b11;
        end else begin
          next_state = 2'b00;
        end
      end
      2'b10: begin
        if (r[0] == 1'b0 && r[1] == 1'b1) begin
          next_state = 2'b10;
        end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
          next_state = 2'b11;
        end else begin
          next_state = 2'b00;
        end
      end
      2'b11: begin
        if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
          next_state = 2'b11;
        end else begin
          next_state = 2'b00;
        end
      end
      default: begin
        next_state = 2'b00;
      end
    endcase
  end
  assign g[0] = (state == 2'b01);
  assign g[1] = (state == 2'b10);
  assign g[2] = (state == 2'b11);
endmodule

