module TopModule (
  input wire clk,
  input wire reset,
  input wire data,
  output wire [3:0] count,
  output reg counting,
  output reg done,
  input wire ack
);
reg [3:0] delay;
  reg [3:0] count_reg;
  assign count = count_reg;
  always @(posedge clk) begin
    if (reset) begin
      done <= 0;
      counting <= 0;
      delay <= 0;
      count_reg <= 0;
    end else begin
      if (counting) begin
        if (ack) begin
          done <= 1;
          counting <= 0;
        end
      end else begin
        if (data == 1 && count_reg == 4'b1101) begin
          delay <= {count_reg, count_reg[3], count_reg[2], count_reg[1]};
          count_reg <= 0;
          counting <= 1;
        end else if (counting) begin
          count_reg <= {count_reg[2:0], data};
        end
      end
    end
  end
endmodule
